INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'flexible', 'adj.', '/ˈfleksəbl/', '柔韧的;灵活的;可变动的', 'The robot dog had very flexible movements and could dance.', '这只机器狗动作非常灵活,还能跳舞。', 'Life and Technology', 1, 0, 'senior', 'wordlist', 'required3', 'U4', 'flexible movements', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attract', 'v.', '/əˈtrækt/', '吸引;引起好感', 'The smart robot quickly attracted the children''s attention.', '这个智能机器人很快吸引了孩子们的注意。', 'Life and Technology', 2, 0, 'senior', 'wordlist', 'required3', 'U4', 'attract attention', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sight', 'n.', '/saɪt/', '看见;视力;视觉', 'At first sight, the robot dog looked just like a real one.', '乍一看,这只机器狗就像真狗一样。', 'Life and Technology', 3, 0, 'senior', 'wordlist', 'required3', 'U4', 'at first sight', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'possess', 'v.', '/pəˈzes/', '具有(特质);拥有', 'Modern robots possess the ability to learn new tasks.', '现代机器人具有学习新任务的能力。', 'Life and Technology', 4, 0, 'senior', 'wordlist', 'required3', 'U4', 'possess a feature', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'impressive', 'adj.', '/ɪmˈpresɪv/', '令人赞叹的;令人敬佩的', 'The robot''s interactive design was really impressive.', '这款机器人的交互设计真的令人赞叹。', 'Life and Technology', 5, 0, 'senior', 'wordlist', 'required3', 'U4', 'an impressive design', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'respond', 'v.', '/rɪˈspɒnd/', '作出反应;响应;回答', 'The robot dog could respond to its owner''s commands.', '这只机器狗能对主人的命令作出反应。', 'Life and Technology', 6, 0, 'senior', 'wordlist', 'required3', 'U4', 'respond to a command', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'view', 'v./n.', '/vjuː/', '观看;仔细察看;把……视为;看法', 'A built-in camera let people view the world through the dog''s eyes.', '内置摄像头让人们透过机器狗的眼睛观看世界。', 'Life and Technology', 7, 0, 'senior', 'wordlist', 'required3', 'U4', 'view the world', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'demanding', 'adj.', '/dɪˈmɑːndɪŋ/', '要求高的;苛求的;难满足的', 'Training a robot to behave well is a demanding task.', '训练机器人表现得当是一项要求很高的任务。', 'Life and Technology', 8, 0, 'senior', 'wordlist', 'required3', 'U4', 'a demanding task', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mature', 'adj.', '/məˈtʃʊə(r)/', '成熟的;发育完全的;明事理的', 'The robot dog could be programmed to act like a mature adult dog.', '这只机器狗可以被设定得像一只成熟的成年犬。', 'Life and Technology', 9, 0, 'senior', 'wordlist', 'required3', 'U4', 'a mature adult', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adult', 'adj./n.', '/ˈædʌlt/', '成年的;成人的;成年人', 'The owner set the robot to behave like an adult dog rather than a puppy.', '主人把机器狗设定成像成年犬而非幼犬那样行事。', 'Life and Technology', 10, 0, 'senior', 'wordlist', 'required3', 'U4', 'an adult dog', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'complain', 'v.', '/kəmˈpleɪn/', '抱怨;投诉;发牢骚', 'Some users complain that smart machines are hard to control.', '一些用户抱怨智能机器很难控制。', 'Life and Technology', 11, 0, 'senior', 'wordlist', 'required3', 'U4', 'complain about', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'hesitation', 'n.', '/ˌhezɪˈteɪʃn/', '犹豫;迟疑不决', 'Without hesitation, the boy started playing with the robot dog.', '男孩毫不犹豫地开始和机器狗玩耍。', 'Life and Technology', 12, 0, 'senior', 'wordlist', 'required3', 'U4', 'without hesitation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'enthusiastic', 'adj.', '/ɪnˌθjuːziˈæstɪk/', '热情的;热心的;满腔热忱的', 'The robot dog gave an enthusiastic response whenever I petted it.', '每当我抚摸它,机器狗都会作出热情的回应。', 'Life and Technology', 13, 0, 'senior', 'wordlist', 'required3', 'U4', 'an enthusiastic response', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'response', 'n.', '/rɪˈspɒns/', '反应;响应;回答', 'The little machine evoked a strong emotional response in me.', '这个小机器在我心中唤起了强烈的情感反应。', 'Life and Technology', 14, 0, 'senior', 'wordlist', 'required3', 'U4', 'an emotional response', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'emotional', 'adj.', '/ɪˈməʊʃənl/', '情感的;情绪的;感情冲动的', 'A robot pet cannot build a true emotional connection with you.', '机器宠物无法与你建立真正的情感联系。', 'Life and Technology', 15, 0, 'senior', 'wordlist', 'required3', 'U4', 'an emotional connection', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'powerful', 'adj.', '/ˈpaʊəfl/', '(作用)强烈的;有权势的;强大的', 'A real emotional connection is powerful and important.', '真正的情感联系是强烈而重要的。', 'Life and Technology', 16, 0, 'senior', 'wordlist', 'required3', 'U4', 'a powerful feeling', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'enthusiasm', 'n.', '/ɪnˈθjuːziæzəm/', '热情;热心;热忱', 'After a while, my enthusiasm for the robot dog began to die down.', '过了一阵子,我对机器狗的热情开始减退。', 'Life and Technology', 17, 0, 'senior', 'wordlist', 'required3', 'U4', 'lose enthusiasm', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'constantly', 'adv.', '/ˈkɒnstəntli/', '始终;一直;不断地', 'I was constantly losing my patience with the robot dog.', '我对这只机器狗一直在失去耐心。', 'Life and Technology', 18, 0, 'senior', 'wordlist', 'required3', 'U4', 'constantly losing patience', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'patience', 'n.', '/ˈpeɪʃns/', '耐心;忍耐力', 'Training a robot pet requires a lot of patience.', '训练机器宠物需要很大的耐心。', 'Life and Technology', 19, 0, 'senior', 'wordlist', 'required3', 'U4', 'lose patience', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'annoy', 'v.', '/əˈnɔɪ/', '使恼怒;使生气', 'It began to annoy me that the robot would not obey.', '机器狗不听话开始让我恼火。', 'Life and Technology', 20, 0, 'senior', 'wordlist', 'required3', 'U4', 'annoy someone', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'breathe', 'v.', '/briːð/', '呼吸', 'Unlike a real pup, the robot dog did not breathe or eat.', '和真小狗不同,机器狗不呼吸也不吃东西。', 'Life and Technology', 21, 0, 'senior', 'wordlist', 'required3', 'U4', 'breathe in and out', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'eventually', 'adv.', '/ɪˈventʃuəli/', '最后;终于', 'Eventually, I stopped calling the machine "he".', '最后,我不再把这台机器叫作“他”。', 'Life and Technology', 22, 0, 'senior', 'wordlist', 'required3', 'U4', 'eventually give up', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'interactive', 'adj.', '/ˌɪntərˈæktɪv/', '交互式的;人机对话的;互动的', 'As an interactive toy, the robot dog was fun to watch.', '作为一个互动玩具,这只机器狗看着很有趣。', 'Life and Technology', 23, 0, 'senior', 'wordlist', 'required3', 'U4', 'an interactive toy', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'remote', 'adj.', '/rɪˈməʊt/', '远程的;遥远的;偏远的', 'With 5G, a doctor can perform remote surgery from far away.', '有了5G,医生可以从远方进行远程手术。', 'Life and Technology', 24, 0, 'senior', 'wordlist', 'required3', 'U4', 'remote surgery', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'surgeon', 'n.', '/ˈsɜːdʒən/', '外科医生', 'The surgeon directed the operation from hundreds of kilometres away.', '这位外科医生从数百公里外指挥了手术。', 'Life and Technology', 25, 0, 'senior', 'wordlist', 'required3', 'U4', 'a heart surgeon', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'surgical', 'adj.', '/ˈsɜːdʒɪkl/', '外科的;外科手术的', 'He used a surgical robot to operate on the patient.', '他用一台手术机器人为病人做了手术。', 'Life and Technology', 26, 0, 'senior', 'wordlist', 'required3', 'U4', 'a surgical robot', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'operation', 'n.', '/ˌɒpəˈreɪʃn/', '手术;操作', 'The whole operation was carried out over a 5G connection.', '整台手术是通过5G连接完成的。', 'Life and Technology', 27, 0, 'senior', 'wordlist', 'required3', 'U4', 'perform an operation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attractive', 'adj.', '/əˈtræktɪv/', '有吸引力的;诱人的', 'What makes remote surgery attractive is that experts need not travel.', '远程手术之所以诱人,是因为专家无需长途奔波。', 'Life and Technology', 28, 0, 'senior', 'wordlist', 'required3', 'U4', 'an attractive idea', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'specialist', 'n.', '/ˈspeʃəlɪst/', '专家;专科医生', 'Leading specialists can now help with operations from far away.', '顶尖专家如今可以从远方协助手术。', 'Life and Technology', 29, 0, 'senior', 'wordlist', 'required3', 'U4', 'a heart specialist', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'operate', 'v.', '/ˈɒpəreɪt/', '动手术;操作;运转', 'The doctor operated on the patient remotely with a robot.', '医生用机器人远程为病人动了手术。', 'Life and Technology', 30, 0, 'senior', 'wordlist', 'required3', 'U4', 'operate on a patient', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lack', 'v./n.', '/læk/', '缺乏;没有;匮乏', 'Until now, doctors lacked a fast and stable Internet connection.', '直到现在,医生还缺乏快速而稳定的网络连接。', 'Life and Technology', 31, 0, 'senior', 'wordlist', 'required3', 'U4', 'a lack of', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'artificial', 'adj.', '/ˌɑːtɪˈfɪʃl/', '人工的;人造的;假的', 'A 3D model of the heart was built using artificial intelligence.', '心脏的三维模型是用人工智能建立的。', 'Life and Technology', 32, 0, 'senior', 'wordlist', 'required3', 'U4', 'artificial intelligence', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'intelligence', 'n.', '/ɪnˈtelɪdʒəns/', '智力;才智;智慧', 'Artificial intelligence can process medical images very quickly.', '人工智能能非常快速地处理医学影像。', 'Life and Technology', 33, 0, 'senior', 'wordlist', 'required3', 'U4', 'artificial intelligence', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'image', 'n.', '/ˈɪmɪdʒ/', '图像;影像;镜像', 'The team studied medical images on a computer screen.', '团队在电脑屏幕上研究医学影像。', 'Life and Technology', 34, 0, 'senior', 'wordlist', 'required3', 'U4', 'medical images', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'conference', 'n.', '/ˈkɒnfərəns/', '(正式)讨论会;会议', 'They used a live video conference link to guide the operating team.', '他们用实时视频会议连接来指导手术团队。', 'Life and Technology', 35, 0, 'senior', 'wordlist', 'required3', 'U4', 'a video conference', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sew', 'v.', '/səʊ/', '缝制;缝补;缝合', 'The surgeon told the team where to cut and where to sew up.', '外科医生告诉团队在哪里切开、在哪里缝合。', 'Life and Technology', 36, 0, 'senior', 'wordlist', 'required3', 'U4', 'sew up', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'chest', 'n.', '/tʃest/', '胸部;胸膛', 'A small camera was placed inside the patient''s chest.', '一台小摄像头被放置在病人的胸腔内。', 'Life and Technology', 37, 0, 'senior', 'wordlist', 'required3', 'U4', 'inside the chest', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'advanced', 'adj.', '/ədˈvɑːnst/', '先进的;高级的', 'Advanced Internet technology saves doctors a lot of travel time.', '先进的网络技术为医生节省了大量出行时间。', 'Life and Technology', 38, 0, 'senior', 'wordlist', 'required3', 'U4', 'advanced technology', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'technique', 'n.', '/tekˈniːk/', '技巧;技艺;工艺', 'This new technique has now been repeated all over China.', '这项新技术如今已在全国各地多次使用。', 'Life and Technology', 39, 0, 'senior', 'wordlist', 'required3', 'U4', 'a new technique', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'apart', 'adv.', '/əˈpɑːt/', '相隔;相距;分开', 'Doctors far apart now have the chance to work together.', '相隔很远的医生如今有机会一起合作。', 'Life and Technology', 40, 0, 'senior', 'wordlist', 'required3', 'U4', 'far apart', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'network', 'n.', '/ˈnetwɜːk/', '网络;网状系统', 'The 5G network is many times faster than the 4G one.', '5G网络比4G网络快很多倍。', 'Life and Technology', 41, 0, 'senior', 'wordlist', 'required3', 'U4', 'the 5G network', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'currently', 'adv.', '/ˈkʌrəntli/', '目前;当前;现时', '5G is faster than the 4G Internet we currently use.', '5G比我们目前使用的4G网络更快。', 'Life and Technology', 42, 0, 'senior', 'wordlist', 'required3', 'U4', 'currently use', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'signal', 'n.', '/ˈsɪɡnəl/', '信号', '5G provides a more stable connection by reducing signal delay.', '5G通过减少信号延迟提供更稳定的连接。', 'Life and Technology', 43, 0, 'senior', 'wordlist', 'required3', 'U4', 'reduce signal delay', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'delay', 'n./v.', '/dɪˈleɪ/', '延迟;延误;拖延', 'With 5G, the delay drops to about one millisecond.', '使用5G,延迟降到大约一毫秒。', 'Life and Technology', 44, 0, 'senior', 'wordlist', 'required3', 'U4', 'signal delay', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'locate', 'v.', '/ləʊˈkeɪt/', '把……安置在;位于;找出……的位置', 'The surgeon was located in one city while the patient was in another.', '外科医生在一座城市,而病人在另一座城市。', 'Life and Technology', 45, 0, 'senior', 'wordlist', 'required3', 'U4', 'be located in', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'relate', 'v.', '/rɪˈleɪt/', '联系;使有联系;把……联系起来', 'This report relates technology to our everyday life.', '这篇报告把科技与我们的日常生活联系起来。', 'Life and Technology', 46, 0, 'senior', 'wordlist', 'required3', 'U4', 'relate to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'soldier', 'n.', '/ˈsəʊldʒə(r)/', '军人;(尤指)士兵', 'Robots are now used to help soldiers carry heavy loads.', '机器人如今被用来帮助士兵搬运重物。', 'Life and Technology', 47, 0, 'senior', 'wordlist', 'required3', 'U4', 'a brave soldier', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'expert', 'n.', '/ˈekspɜːt/', '专家;行家;能手', 'A team of experts studied a 3D model before the operation.', '手术前一组专家研究了一个三维模型。', 'Life and Technology', 48, 0, 'senior', 'wordlist', 'required3', 'U4', 'a team of experts', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'effective', 'adj.', '/ɪˈfektɪv/', '有效的;产生预期结果的', '5G has become an effective tool for long-distance surgery.', '5G已成为远程手术的一种有效工具。', 'Life and Technology', 49, 0, 'senior', 'wordlist', 'required3', 'U4', 'an effective tool', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'instruct', 'v.', '/ɪnˈstrʌkt/', '指示;命令;吩咐', 'The expert used a video link to instruct the operating team.', '专家通过视频连接指示手术团队。', 'Life and Technology', 50, 0, 'senior', 'wordlist', 'required3', 'U4', 'instruct the team', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u4.01', '①must / can''t(couldn''t) have done(对过去的肯定/否定推测)', 'A2', 10, '上外版必修第三册 U4 — 有确凿证据时对过去作肯定推测用 must have done;有证据断定过去不可能时用 can''t / couldn''t have done。语境给出明确依据(看见结果、已知事实)才用,区别于单纯可能性。', 1, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u4.02', '②should(n''t) have done & needn''t have done(本应/不该/本不必)', 'A2', 10, '上外版必修第三册 U4 — 本应做却没做用 should have done;不该做却做了用 shouldn''t have done;本不必做却做了用 needn''t have done。语境含责备、后悔或“白做了”的暗示。', 2, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s3u4.03', '③may / might / could have done(对过去的可能性推测)', 'A2', 10, '上外版必修第三册 U4 — 对过去拿不准、只是一种可能时用 may / might / could have done(语气不确定),区别于 must(确定)与 should(责备)。', 3, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'Lily can''t find her e-reader anywhere. She ____ left it on the subway, because that''s the only place she used it today.', 'must have', 'can''t have', 'needn''t have', 'shouldn''t have', 'A', '唯一用过的地方 → 几乎可以断定;对过去的确定肯定推测用 must have done。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The robot dog is moving and dancing, so someone ____ already charged its battery.', 'can''t have', 'must have', 'may not have', 'needn''t have', 'B', '机器狗在动 → 有确凿证据断定电池已充;肯定推测用 must have done。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The screen is completely black and silent. The computer ____ crashed during the update.', 'can''t have', 'needn''t have', 'must have', 'shouldn''t have', 'C', '黑屏无声这一结果是证据 → 确定它崩溃了,用 must have done。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'Dr Guo was in Guangzhou the whole morning, so he ____ been in the Beijing operating room himself.', 'must have', 'may have', 'should have', 'can''t have', 'D', '整个上午都在广州这一事实 → 断定不可能在北京;否定推测用 can''t have done。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'Tom never studied programming, so he ____ written that complex robot code on his own.', 'couldn''t have', 'must have', 'needn''t have', 'should have', 'A', '从没学过编程 → 断定他不可能独立写出;否定推测用 couldn''t have done。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The lab door was locked all night, so the thief ____ got in through it.', 'must have', 'can''t have', 'may have', 'needn''t have', 'B', '门整夜上锁这一事实排除可能 → 用 can''t have done。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'Her phone is fully charged and warm, so she ____ been using it just a moment ago.', 'can''t have', 'shouldn''t have', 'must have', 'needn''t have', 'C', '满电又发热是直接证据 → 确定刚用过,用 must have done。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The surgery succeeded with a perfect signal, so the 5G connection ____ failed at any point.', 'must have', 'may have', 'should have', 'can''t have', 'D', '手术成功、信号完美这一结果 → 断定连接没断过;否定推测用 can''t have done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'All the files are gone from the desktop, so someone ____ deleted them by mistake.', 'must have', 'can''t have', 'needn''t have', 'shouldn''t have', 'A', '文件全没了这一结果 → 断定有人误删;肯定推测用 must have done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'Jack hates robots and refused to come, so it ____ been him at the AI exhibition.', 'must have', 'can''t have', 'might have', 'needn''t have', 'B', '讨厌机器人又拒绝来这一事实 → 断定不可能是他;否定推测用 can''t have done。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The model of the heart was ready in minutes, so the AI ____ processed the images very fast.', 'can''t have', 'shouldn''t have', 'must have', 'needn''t have', 'C', '几分钟就建好模型这一结果 → 确定处理很快,用 must have done。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The whole house lost power last night, so the smart camera ____ recorded anything then.', 'must have', 'may have', 'should have', 'can''t have', 'D', '整晚停电这一事实 → 断定不可能录到东西;否定推测用 can''t have done。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The delay dropped to one millisecond, so they ____ switched to the 5G network already.', 'must have', 'can''t have', 'needn''t have', 'shouldn''t have', 'A', '延迟降到1毫秒这一可观察结果 → 确定已切到5G,用 must have done。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'She knows nothing about surgery, so she ____ directed that operation by herself.', 'must have', 'couldn''t have', 'may have', 'needn''t have', 'B', '完全不懂手术这一事实 → 断定她不可能独自指挥;否定推测用 couldn''t have done。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'His fingerprint unlocked the device instantly, so the phone ____ recognised him at once.', 'can''t have', 'shouldn''t have', 'must have', 'needn''t have', 'C', '指纹瞬间解锁这一结果 → 确定手机已识别他,用 must have done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The robot was switched off all day, so it ____ moved on its own this afternoon.', 'must have', 'might have', 'should have', 'can''t have', 'D', '整天关机这一事实 → 断定不可能自己动;否定推测用 can''t have done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'There are wet footprints leading to the lab, so someone ____ walked in just now.', 'must have', 'can''t have', 'needn''t have', 'shouldn''t have', 'A', '湿脚印这一直接证据 → 确定刚有人进来,用 must have done。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The patient lives in a remote village with no signal, so he ____ joined the video call from there.', 'must have', 'can''t have', 'may have', 'should have', 'B', '偏远村庄没信号这一事实 → 断定不可能从那里接入;否定推测用 can''t have done。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'The new app shows my exact steps, so it ____ used the phone''s sensors all along.', 'can''t have', 'shouldn''t have', 'must have', 'needn''t have', 'C', '能显示精确步数这一结果 → 确定一直在用传感器,用 must have done。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.01'), 'Anna was abroad with no Internet last week, so she ____ replied to that online survey.', 'must have', 'might have', 'needn''t have', 'can''t have', 'D', '上周在国外无网这一事实 → 断定不可能回复;否定推测用 can''t have done。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'I forgot to back up my files before the update. I ____ saved them first.', 'should have', 'can''t have', 'must have', 'may have', 'A', '本该先保存却忘了 → 责备/后悔“本应做而未做”用 should have done。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The course turned out to be far too hard for me. I ____ signed up for it.', 'must have', 'shouldn''t have', 'needn''t have', 'could have', 'B', '报了不该报的难课 → “不该做却做了”用 shouldn''t have done。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The robot pet looks after itself, so I ____ worried about feeding it.', 'should have', 'can''t have', 'needn''t have', 'must have', 'C', '其实根本不用喂却担心了 → “本不必做却做了”用 needn''t have done。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'You missed the deadline for the survey. You ____ submitted it earlier.', 'can''t have', 'needn''t have', 'may have', 'should have', 'D', '本应早点交却错过 → 责备“本应做而未做”用 should have done。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'He shut down the whole network during the test by mistake. He ____ touched that button.', 'shouldn''t have', 'must have', 'needn''t have', 'could have', 'A', '不该碰那个键却碰了 → “不该做却做了”用 shouldn''t have done。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The instructions were printed on the box all along, so we ____ called the support line.', 'should have', 'needn''t have', 'can''t have', 'must have', 'B', '说明就在盒上,根本没必要打电话 → “本不必做却做了”用 needn''t have done。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'Grandpa got lost using the new app. Someone ____ shown him how it works first.', 'can''t have', 'needn''t have', 'should have', 'may have', 'C', '本该先教他用却没教 → “本应做而未做”用 should have done。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The robot dog let the boy down in the end. He ____ expected it to feel like a real pet.', 'must have', 'needn''t have', 'could have', 'shouldn''t have', 'D', '不该抱有那样的期待却抱了 → “不该做却做了”用 shouldn''t have done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'It turned out the doctor didn''t need to fly over, so he ____ booked the plane ticket.', 'needn''t have', 'should have', 'can''t have', 'must have', 'A', '其实不必飞过去却订了票 → “本不必做却做了”用 needn''t have done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'I ignored the low-battery warning, and the tablet died in class. I ____ charged it last night.', 'can''t have', 'should have', 'needn''t have', 'may have', 'B', '本应昨晚充电却没充 → 后悔“本应做而未做”用 should have done。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'She typed her password into a fake website. She really ____ trusted that link.', 'must have', 'needn''t have', 'shouldn''t have', 'could have', 'C', '不该信那个链接却信了 → “不该做却做了”用 shouldn''t have done。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The update was automatic the whole time, so you ____ downloaded it by hand.', 'should have', 'can''t have', 'must have', 'needn''t have', 'D', '本来自动更新,手动下载是白做 → “本不必做却做了”用 needn''t have done。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The presentation failed because no one tested the link. We ____ checked it beforehand.', 'should have', 'can''t have', 'needn''t have', 'may have', 'A', '本应事先测试却没测 → 责备“本应做而未做”用 should have done。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'He spent the whole night arguing about robots online. He ____ wasted his time like that.', 'must have', 'shouldn''t have', 'needn''t have', 'could have', 'B', '不该那样浪费时间却浪费了 → “不该做却做了”用 shouldn''t have done。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The lost-and-found office already had her e-reader, so she ____ bought a new one.', 'should have', 'can''t have', 'needn''t have', 'must have', 'C', '失物招领处有,买新机是白买 → “本不必做却做了”用 needn''t have done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The robot couldn''t learn the trick because the boy gave up too soon. He ____ been more patient.', 'can''t have', 'needn''t have', 'may have', 'should have', 'D', '本应更有耐心却没有 → 责备“本应做而未做”用 should have done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'You posted my private photo without asking. You ____ done that.', 'shouldn''t have', 'must have', 'needn''t have', 'could have', 'A', '不该未经允许就发却发了 → “不该做却做了”用 shouldn''t have done。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The free trial covered everything we wanted, so we ____ paid for the full version.', 'should have', 'needn''t have', 'can''t have', 'must have', 'B', '免费版已够用,付费是白付 → “本不必做却做了”用 needn''t have done。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'The car''s sensors were clearly broken, yet he drove anyway. He ____ ignored the warning.', 'must have', 'needn''t have', 'shouldn''t have', 'could have', 'C', '不该无视警告却无视了 → “不该做却做了”用 shouldn''t have done。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.02'), 'We lost the data because nobody saved a copy. Someone ____ made a backup.', 'can''t have', 'needn''t have', 'may have', 'should have', 'D', '本应有人备份却没人备份 → 责备“本应做而未做”用 should have done。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'Sophia is late this morning, though she usually isn''t. She ____ got stuck in traffic.', 'may have', 'must have', 'can''t have', 'needn''t have', 'A', '只是猜一种可能、并不确定 → 可能性推测用 may have done。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'I''m not sure where my smartphone is. I ____ left it in the classroom, but I can''t remember.', 'must have', 'might have', 'can''t have', 'shouldn''t have', 'B', '“记不清了” → 不确定的可能性,用 might have done。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The robot could have danced for us, but its battery ____ run out before the show.', 'must have', 'needn''t have', 'could have', 'shouldn''t have', 'C', '对原因只是一种猜测、留有余地 → 用 could have done。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'Nobody answered the video call. The specialist ____ been busy with another patient.', 'must have', 'can''t have', 'needn''t have', 'may have', 'D', '原因不确定、只是一种可能 → 用 may have done。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The signal dropped for a second. Someone nearby ____ turned on a microwave.', 'might have', 'must have', 'can''t have', 'shouldn''t have', 'A', '对干扰原因只是猜测 → 不确定的可能性,用 might have done。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'I can''t find the file. I ____ saved it under a different name, but I''m not sure.', 'must have', 'may have', 'can''t have', 'needn''t have', 'B', '“我不确定” → 一种可能,用 may have done。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The app crashed once yesterday. A bug in the update ____ caused it.', 'must have', 'can''t have', 'could have', 'shouldn''t have', 'C', '对原因留有余地的推测 → 用 could have done。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'Max hasn''t replied yet. He ____ missed my message among so many notifications.', 'must have', 'can''t have', 'needn''t have', 'might have', 'D', '只是一种可能的解释、并不肯定 → 用 might have done。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The smart speaker stopped halfway. The Wi-Fi ____ dropped for a moment.', 'may have', 'must have', 'can''t have', 'shouldn''t have', 'A', '对中断原因不确定 → 可能性推测用 may have done。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'She looks tired today. She ____ stayed up late testing the new robot, but who knows.', 'must have', 'might have', 'can''t have', 'needn''t have', 'B', '“谁知道呢” → 纯属猜测,用 might have done。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The package isn''t here yet. The delivery ____ been delayed by the heavy rain.', 'must have', 'can''t have', 'could have', 'shouldn''t have', 'C', '对延误原因的开放性猜测 → 用 could have done。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'I don''t know why the robot stopped. Its sensors ____ got a little dusty.', 'must have', 'can''t have', 'needn''t have', 'may have', 'D', '“不知道为什么” → 只是一种可能,用 may have done。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'George didn''t hand in the report. His computer ____ broken down, though I''m guessing.', 'might have', 'must have', 'can''t have', 'shouldn''t have', 'A', '“我只是猜” → 不确定可能性,用 might have done。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The download was slow tonight. Many people ____ been using the network at the same time.', 'must have', 'may have', 'can''t have', 'needn''t have', 'B', '对慢速原因留余地 → 可能性推测用 may have done。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The old couple smiled during the VR trip. It ____ reminded them of an earlier journey.', 'must have', 'can''t have', 'might have', 'shouldn''t have', 'C', '对他们微笑原因的温和猜测 → 用 might have done。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The accident on the test track ____ been prevented, but no one noticed the warning in time.', 'must have', 'can''t have', 'needn''t have', 'could have', 'D', '“本可以避免却没避免” → 过去可能而未发生,用 could have done。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'Nobody is sure who fixed the robot. A volunteer ____ done it during the lunch break.', 'may have', 'must have', 'can''t have', 'shouldn''t have', 'A', '“没人确定” → 一种可能,用 may have done。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The screen flickered briefly. A loose cable ____ caused the problem, I suppose.', 'must have', 'might have', 'can''t have', 'needn''t have', 'B', '“我猜” → 不确定的可能解释,用 might have done。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'The patient woke up early after surgery. The new technique ____ helped him recover faster.', 'must have', 'can''t have', 'may have', 'shouldn''t have', 'C', '对恢复快的原因不下定论 → 可能性推测用 may have done。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required3' AND unit='U4' AND code='s3u4.03'), 'We''re not certain why the call ended. The 5G link ____ lost the signal for an instant.', 'must have', 'can''t have', 'needn''t have', 'might have', 'D', '“不确定原因” → 一种可能,用 might have done。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Life with a Robot Dog', 'When the boy first saw the robot dog, he treated it just like a real pet. Without any hesitation, he played with it and stroked it. The dog gave an enthusiastic response, and at first this evoked a strong emotional feeling in him. The robot looked good and its movements were flexible: it could stretch, dance and jump. Best of all, it did not need to be fed and it would never breathe or grow old. However, as the days passed, the boy realised that the relationship was limited. He could not train the robot to respond to his commands, even though it was built to learn. He constantly lost his patience and began to feel annoyed. A true emotional connection, he understood, is powerful and important, and that was something the machine could never give him. Eventually he stopped calling it "he" and started calling it "the robot". As a clever toy it was a success, but as a real pet it let him down.', '记叙·一只机器狗带来的体验', 166, '[{"q":"How did the boy feel about the robot dog at the very beginning?","answer":"A","options":["He treated it warmly, as if it were a real pet.","He was afraid of it and kept away.","He thought it was ugly and useless.","He refused to touch it at all."],"explanation":"开头说他毫不犹豫地和它玩耍、抚摸它,把它当真宠物 → 概括为热情对待。"},{"q":"Why did the boy''s feelings change over time?","answer":"B","options":["The robot dog became too expensive to keep.","He could not build a real emotional bond with the machine.","His parents took the robot away.","The robot dog needed too much food."],"explanation":"文中说关系有限、无法建立真正的情感联系 → 转述。其余与原文不符(机器不用喂)。"},{"q":"What does calling it \"the robot\" instead of \"he\" suggest?","answer":"A","options":["He no longer saw it as a living companion.","He had grown to love it even more.","He decided to buy a second one.","He thought it had become a real dog."],"explanation":"由“他”改称“机器”暗示他不再把它当作有生命的伙伴 → 推断转述。"}]'::jsonb, '[{"word":"hesitation","cn":"犹豫"},{"word":"flexible","cn":"灵活的"},{"word":"enthusiastic","cn":"热情的"},{"word":"emotional","cn":"情感的"},{"word":"patience","cn":"耐心"}]'::jsonb, 2, 'required3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Surgery over 5G', 'The future of surgery is looking remote. Recently doctors in China directed a heart operation on a patient who was hundreds of kilometres away, using a fast 5G connection. What makes long-distance surgery attractive is that leading specialists can help without being present in the operating room. All they need is a fast and stable Internet link, which until now they lacked. To prepare, the expert team studied a 3D model of the heart built by artificial intelligence from medical images, and then worked out a plan. During the operation they used a live video conference link to instruct the local team on where to cut and where to sew up. The 5G network is many times faster than the 4G we currently use, and it greatly reduces signal delay. With 4G, delays can be between twenty and eighty milliseconds; with 5G they drop to about one. This tiny difference matters most when a doctor operates remotely with a robot, because then every millisecond counts.', '说明·5G远程手术', 165, '[{"q":"According to the text, why is long-distance surgery attractive?","answer":"B","options":["It makes operations completely free of charge.","Top experts can take part without travelling to the patient.","It removes the need for any local doctors.","It works without any Internet connection."],"explanation":"文中说顶尖专家无需亲临手术室即可参与 → 转述。其余未提或与文相反。"},{"q":"What role did artificial intelligence play before the operation?","answer":"C","options":["It performed the whole operation by itself.","It replaced the patient''s heart with a new one.","Using medical scans, it created a 3D heart model for the team.","It chose which hospital to use."],"explanation":"原文说AI用医学影像建出心脏三维模型 → 转述。"},{"q":"Why does the reduced signal delay matter most during robot surgery?","answer":"D","options":["Because robots cannot work with any delay at all.","Because 4G is faster than 5G for robots.","Because the patient must control the robot.","Because every millisecond counts when a robot does the cutting."],"explanation":"末句说机器人远程操作时每一毫秒都重要 → 转述。"}]'::jsonb, '[{"word":"remote","cn":"远程的"},{"word":"specialist","cn":"专家"},{"word":"conference","cn":"会议"},{"word":"signal","cn":"信号"},{"word":"delay","cn":"延迟"}]'::jsonb, 2, 'required3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'What Artificial Intelligence Can Do', 'Artificial intelligence, often called AI, is software that can learn from data and make decisions. Today it already helps in many parts of daily life. In hospitals, AI can study thousands of medical images in seconds and point out problems a tired human eye might miss. On your phone, it suggests the next word as you type and recommends songs you may enjoy. In factories, smart machines work all day without losing patience or growing bored. Yet AI is not perfect. It only knows what it has been taught, so it can make strange mistakes that no person would make. It also lacks real feelings, which means it cannot truly understand why a joke is funny or why a piece of music moves us. Many experts believe the best results come when people and machines work together: the computer handles the boring, repeated tasks, while humans bring judgement, care and imagination. Used wisely, AI is a powerful tool rather than a replacement for human beings.', '说明·人工智能的能力与局限', 165, '[{"q":"What is one way AI helps in hospitals, according to the text?","answer":"A","options":["It quickly examines many medical images and spots problems.","It decides which patients deserve treatment.","It refuses to work with human doctors.","It builds the hospital buildings."],"explanation":"文中说AI能在几秒内研究大量医学影像并指出问题 → 转述。"},{"q":"What weakness of AI does the writer point out?","answer":"B","options":["It is always slower than a human worker.","It has no real feelings and can make odd mistakes.","It cannot store any information.","It needs to eat and rest like people."],"explanation":"原文说AI缺乏真正情感、会犯奇怪错误 → 转述。"},{"q":"What does the writer suggest is the best way to use AI?","answer":"C","options":["Replace all human workers with machines.","Stop using AI in daily life completely.","Have humans and computers cooperate, each handling what it does best.","Trust AI to make every decision alone."],"explanation":"文末说人机合作效果最好,机器做重复活、人带来判断与想象 → 转述。"}]'::jsonb, '[{"word":"artificial","cn":"人工的"},{"word":"intelligence","cn":"智力"},{"word":"image","cn":"图像"},{"word":"lack","cn":"缺乏"},{"word":"powerful","cn":"强大的"}]'::jsonb, 2, 'required3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Cars That Drive Themselves', 'Imagine sitting in a car that drives itself while you read or rest. Self-driving cars use cameras and sensors to view the road, and a computer decides when to turn, slow down or stop. Supporters say such cars could make our roads much safer, because most accidents are caused by human mistakes like looking at a phone. A tireless computer never gets sleepy and can respond to danger in a fraction of a second. These cars could also help people who cannot drive, such as the old or the blind, to move around freely. Still, many people are not yet ready to trust them. In one survey, more than half said they would not ride in a self-driving car, and most wanted a human in the driver''s seat who could take control when needed. There are hard questions too: if the car causes a crash, who is to blame? Until these worries are settled, most experts think people and machines should share the wheel for years to come.', '议论·自动驾驶汽车的利弊', 168, '[{"q":"Why do supporters believe self-driving cars could be safer?","answer":"D","options":["They are much cheaper than ordinary cars.","They can only be used on empty roads.","They travel far more slowly than people drive.","A computer never gets tired and reacts to danger very fast."],"explanation":"文中说不知疲倦的电脑能极快反应,且多数事故由人为失误引起 → 转述。"},{"q":"What did most people in the survey want?","answer":"A","options":["A person ready to take over the wheel if necessary.","Cars with no controls at all.","To ban self-driving cars completely.","Faster cars with no sensors."],"explanation":"原文说多数人希望驾驶座上有人可在必要时接管 → 转述。"},{"q":"What unsolved question does the writer raise?","answer":"B","options":["How to make the cars change colour.","Who should be blamed if a self-driving car causes a crash.","Why blind people dislike cars.","When phones will replace cars."],"explanation":"文中提出若自动驾驶车致事故由谁负责 → 转述。"}]'::jsonb, '[{"word":"view","cn":"观看;察看"},{"word":"respond","cn":"作出反应"},{"word":"survey","cn":"调查"},{"word":"blame","cn":"责怪"}]'::jsonb, 2, 'required3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Travelling Without Leaving Home', 'An elderly couple sat side by side, each wearing a pair of large glasses. They could no longer travel far because of their age, and this made them sad. Then their grandson, who works in a busy city, brought them a virtual reality headset. As soon as they put it on, the room around them seemed to disappear. Suddenly they were standing on a warm beach in Thailand, a place they had visited many years before. They could turn their heads and look around at the blue sea and the green islands. The wife smiled and said it felt as real as the day they first went there. With VR, they could also visit countries they had never seen, such as France and South Korea, all without leaving their sofa. The grandson explained that the same technology is now used to treat lonely or worried minds, and even to help students explore places that are too far or too dangerous to reach in person.', '记叙·VR帮助老人重游故地', 164, '[{"q":"Why were the elderly couple sad at first?","answer":"C","options":["Their grandson had moved abroad forever.","They had lost all their old photos.","Their age stopped them from travelling far.","They disliked their quiet sofa."],"explanation":"文中说他们因年纪大无法远行而难过 → 转述。"},{"q":"What did the wife feel during the VR experience?","answer":"D","options":["It was frightening and made her dizzy.","It was boring compared with photos.","It reminded her of nothing at all.","She found the experience as vivid as their original trip there."],"explanation":"原文说妻子笑着说感觉和当年第一次去时一样真实 → 转述。"},{"q":"What other use of VR does the grandson mention?","answer":"A","options":["Helping worried minds and letting students explore far-off places.","Cooking meals for the whole family.","Replacing real beaches with fake ones forever.","Teaching dogs to do new tricks."],"explanation":"文末说同样技术用于治疗孤独焦虑的心理、帮学生探索遥远或危险之地 → 转述。"}]'::jsonb, '[{"word":"elderly","cn":"上了年纪的"},{"word":"virtual reality","cn":"虚拟现实"},{"word":"headset","cn":"头戴设备"}]'::jsonb, 2, 'required3', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Apps in Our Pockets', 'Not long ago, you needed a map, a dictionary, a camera and a wallet to get through the day. Now a single phone, full of smart apps, can do all of these and more. With a few taps you can call a taxi, order dinner, pay a bill or learn a new language on the bus home. These apps save us time and make life more convenient, and many of them learn from how we use them, so the more you tap, the better they seem to know you. Yet there is a price for all this ease. Apps collect a great deal of information about where we go and what we like, and not everyone is comfortable with that. Some people also find it hard to put their phones down, checking them constantly even when nothing new has happened. Experts advise us to enjoy the help that apps offer but to stay in charge: turn off the screen now and then, and remember that the most important moments happen in the real world, not behind the glass.', '说明·智能App如何改变日常', 178, '[{"q":"What is the writer''s main point about smart apps?","answer":"B","options":["They are useless and should be deleted.","They make life easier but should be used with care.","They can fully replace real-world friends.","They never collect any personal information."],"explanation":"全文说App方便但有代价、应自己做主 → 概括主旨。"},{"q":"What concern does the writer raise about apps?","answer":"C","options":["They make phones too heavy to carry.","They only work without the Internet.","They collect plenty of details on our movements and tastes.","They cost nothing to use."],"explanation":"文中说App收集大量关于我们行踪与喜好的信息 → 转述。"},{"q":"What advice do the experts give?","answer":"D","options":["Never use any app again.","Spend even more time on your phone.","Buy a new phone every month.","Enjoy the apps but stay in charge and look up from the screen."],"explanation":"文末建议享受便利同时自己做主、时常放下手机 → 转述。"}]'::jsonb, '[{"word":"convenient","cn":"方便的"},{"word":"constantly","cn":"不断地"},{"word":"information","cn":"信息"}]'::jsonb, 2, 'required3', 'U4', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'A Smart Home', 'My family recently turned our flat into a smart home, and it has changed our daily life. In the morning, the lights come on by (1)____ before I even open my eyes. I just say a word, and the speaker (2)____ to my voice and plays the news. The heating is (3)____, so the rooms are warm enough but never too hot. When I leave, a single tap on my phone can (4)____ off everything at once. Cameras let me (5)____ the front door from anywhere in the city. At first my grandmother (6)____ that all this was too complicated, but soon she learned to use it without any (7)____. Of course, the system is not (8)____. Once the Internet went down and nothing worked, which (9)____ me a little. Still, used (10)____, a smart home saves time and makes life more comfortable.', 143, 2, '[{"q":"1","answer":"A","options":["itself","themselves","themself","ourselves"],"explanation":"灯自己亮起 → 单数无生命主语用 itself。"},{"q":"2","answer":"B","options":["complains","responds","breathes","lacks"],"explanation":"音箱对声音作出反应 → respond to。"},{"q":"3","answer":"C","options":["remote","demanding","flexible","mature"],"explanation":"供暖灵活调节 → flexible。"},{"q":"4","answer":"D","options":["view","attract","sew","turn"],"explanation":"一键关掉一切 → turn off。"},{"q":"5","answer":"A","options":["view","annoy","breathe","possess"],"explanation":"随处查看前门 → view。"},{"q":"6","answer":"B","options":["responded","complained","located","operated"],"explanation":"奶奶抱怨太复杂 → complain。"},{"q":"7","answer":"C","options":["signal","delay","hesitation","network"],"explanation":"毫无犹豫地学会 → without any hesitation。"},{"q":"8","answer":"D","options":["advanced","interactive","powerful","perfect"],"explanation":"系统并非完美 → perfect。"},{"q":"9","answer":"A","options":["annoyed","attracted","viewed","instructed"],"explanation":"断网让我有点恼火 → annoy。"},{"q":"10","answer":"B","options":["currently","wisely","constantly","apart"],"explanation":"明智地使用 → wisely。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'Learning Online', 'Last winter my school moved its lessons online, and I had to study from home through a screen. At first it was a real (1)____, because I missed sitting with my classmates. The video link sometimes had a long (2)____, and the teacher''s voice broke up. I had to be (3)____ enough to switch between apps and find the right page quickly. Slowly, though, I began to (4)____ some real advantages. I could (5)____ a recorded lesson again whenever I did not understand something. I no longer wasted time travelling, so I had (6)____ hours to read. Online study also asked me to be more (7)____: nobody stood beside me, so I had to (8)____ myself to follow the timetable. By the end of the term, I had become a far more (9)____ learner. Both kinds of study, I realised, have their own (10)____.', 144, 2, '[{"q":"1","answer":"C","options":["signal","soldier","struggle","surgeon"],"explanation":"起初很吃力 → a real struggle。"},{"q":"2","answer":"D","options":["image","chest","network","delay"],"explanation":"视频常有长延迟 → delay。"},{"q":"3","answer":"A","options":["flexible","remote","emotional","mature"],"explanation":"灵活切换应用 → flexible。"},{"q":"4","answer":"B","options":["sew","see","lack","annoy"],"explanation":"开始看到一些好处 → see。"},{"q":"5","answer":"C","options":["complain","breathe","view","possess"],"explanation":"重看录播课 → view。"},{"q":"6","answer":"D","options":["remote","advanced","surgical","extra"],"explanation":"省下时间→有额外的时间 → extra。"},{"q":"7","answer":"A","options":["independent","interactive","impressive","artificial"],"explanation":"在线学习要求更独立 → independent。"},{"q":"8","answer":"B","options":["attract","discipline","instruct","operate"],"explanation":"约束自己守时间表 → discipline myself。"},{"q":"9","answer":"C","options":["demanding","currently","effective","constantly"],"explanation":"成为更高效的学习者 → effective。"},{"q":"10","answer":"D","options":["delays","signals","networks","strengths"],"explanation":"两种学习各有长处 → strengths。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'A Watch That Watches You', 'My new smartwatch does far more than tell the time. All day it quietly (1)____ how many steps I take and how fast my heart beats. If I sit too long, it gently (2)____ me to stand up and move. One evening it warned me that my heart rate looked (3)____, so I went to see a doctor. A (4)____ checked me and said the watch had spotted an early problem. This small device can (5)____ a great deal of useful information about my health. It is (6)____ to charge and easy to wear, so I almost forget it is there. Of course, a watch cannot (7)____ a real doctor, and I should not let it (8)____ me about every tiny change. But used (9)____, it is a (10)____ tool that helps me take better care of myself.', 138, 2, '[{"q":"1","answer":"A","options":["records","complains","breathes","lacks"],"explanation":"整天默默记录步数心率 → record。"},{"q":"2","answer":"B","options":["attracts","reminds","operates","sews"],"explanation":"提醒我站起来 → remind。"},{"q":"3","answer":"C","options":["flexible","remote","unusual","mature"],"explanation":"心率看起来异常 → unusual。"},{"q":"4","answer":"D","options":["soldier","signal","network","specialist"],"explanation":"专科医生检查我 → specialist。"},{"q":"5","answer":"A","options":["possess","annoy","instruct","view"],"explanation":"能掌握大量健康信息 → possess。"},{"q":"6","answer":"B","options":["demanding","convenient","emotional","artificial"],"explanation":"充电方便 → convenient。"},{"q":"7","answer":"C","options":["relate","locate","replace","respond"],"explanation":"手表不能取代真正医生 → replace。"},{"q":"8","answer":"D","options":["attract","breathe","sew","worry"],"explanation":"不该让它为每点小变化担忧 → worry。"},{"q":"9","answer":"A","options":["wisely","currently","constantly","apart"],"explanation":"明智地使用 → wisely。"},{"q":"10","answer":"B","options":["remote","powerful","surgical","interactive"],"explanation":"是个强大的工具 → powerful。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'Grandpa and the Tablet', 'When we gave Grandpa a tablet, he stared at it with a little (1)____, unsure where to begin. The bright screen did not (2)____ him at first, and he said the buttons were too small. We sat with him (3)____ and showed him, step by step, how to send a message and make a video call. He needed a lot of (4)____, because he often forgot which icon to press. But he never (5)____; instead he tried again and again. (6)____, after a few weeks, his face broke into a huge smile: he had called his old friend, who lives far (7)____ in another city. Now the tablet helps him stay (8)____ to people he loves. Technology had once seemed (9)____ to him, but kindness and patience made it friendly. The lesson is simple: with the right help, even an older person can (10)____ a useful new skill.', 148, 2, '[{"q":"1","answer":"C","options":["signal","delay","hesitation","chest"],"explanation":"带着一点犹豫盯着平板 → hesitation。"},{"q":"2","answer":"D","options":["respond","complain","operate","attract"],"explanation":"屏幕起初没吸引他 → attract。"},{"q":"3","answer":"A","options":["patiently","currently","apart","miserably"],"explanation":"耐心地陪他坐着 → patiently。"},{"q":"4","answer":"B","options":["network","patience","soldier","image"],"explanation":"需要很多耐心 → patience。"},{"q":"5","answer":"C","options":["viewed","located","complained","possessed"],"explanation":"他从不抱怨 → complain。"},{"q":"6","answer":"D","options":["Constantly","Currently","Hardly","Eventually"],"explanation":"几周后终于 → eventually。"},{"q":"7","answer":"A","options":["apart","down","off","out"],"explanation":"住在很远的另一城市 → far apart。"},{"q":"8","answer":"B","options":["advanced","connected","surgical","mature"],"explanation":"帮他与所爱的人保持联系 → connected。"},{"q":"9","answer":"C","options":["flexible","effective","demanding","powerful"],"explanation":"科技曾让他觉得难应付 → demanding。"},{"q":"10","answer":"D","options":["annoy","breathe","sew","master"],"explanation":"掌握一项有用新技能 → master。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'The School Robot Contest', 'Our school held a robot contest, and my team spent a month building a machine that could (1)____ to simple voice orders. Designing it was a (2)____ job that tested our patience every day. The first model was clumsy, but each new version had more (3)____ joints and smoother moves. On the day of the contest, our robot did something truly (4)____: it picked up a cup and placed it on a tray. The judges were clearly (5)____ by its design. We were so (6)____ that we cheered out loud. Of course, our little machine could not really (7)____ feelings, yet watching it work gave us a strong sense of pride. The contest taught us that good (8)____ and teamwork matter more than fancy parts. (9)____, we did not win first prize, but we learned more than any (10)____ in a book could teach.', 144, 2, '[{"q":"1","answer":"A","options":["respond","complain","lack","sew"],"explanation":"机器对语音命令作出反应 → respond。"},{"q":"2","answer":"B","options":["remote","demanding","emotional","currently"],"explanation":"要求高、考验耐心的活 → demanding。"},{"q":"3","answer":"C","options":["surgical","artificial","flexible","mature"],"explanation":"更灵活的关节 → flexible。"},{"q":"4","answer":"D","options":["demanding","remote","powerful","impressive"],"explanation":"做了真正令人赞叹的事 → impressive。"},{"q":"5","answer":"A","options":["attracted","annoyed","located","instructed"],"explanation":"评委被设计吸引 → attract(被动)。"},{"q":"6","answer":"B","options":["remote","enthusiastic","surgical","artificial"],"explanation":"我们非常热情兴奋 → enthusiastic。"},{"q":"7","answer":"C","options":["view","operate","possess","instruct"],"explanation":"机器并不能真正拥有情感 → possess。"},{"q":"8","answer":"D","options":["signal","delay","soldier","technique"],"explanation":"好的技艺与团队合作 → technique。"},{"q":"9","answer":"A","options":["Eventually","Constantly","Currently","Hardly"],"explanation":"最后我们没拿第一 → eventually。"},{"q":"10","answer":"B","options":["image","lesson","chest","network"],"explanation":"比书上任何一课学到的都多 → lesson。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'Being Polite in the Digital Age', 'Technology has given us many fast ways to talk, but it has also raised new questions about how to be (1)____. When a message arrives, we feel we must (2)____ at once, even in the middle of a meal. Some people check their phones (3)____, glancing at the screen while a friend is still speaking. This habit can (4)____ the people around us, who feel ignored. Good manners online are much the same as in real life. We should not (5)____ that everyone is free the moment we send a text. It is kind to leave a clear (6)____ to a friend''s question rather than a cold one-word reply. We should also be careful not to share someone''s photo without asking, because that can hurt an (7)____ bond. The most (8)____ thing, perhaps, is to remember the person on the other side of the screen. Put the phone down (9)____, look up, and give the people in front of you your full (10)____.', 163, 2, '[{"q":"1","answer":"C","options":["remote","surgical","polite","artificial"],"explanation":"如何做到礼貌 → polite。"},{"q":"2","answer":"D","options":["possess","breathe","sew","respond"],"explanation":"觉得必须立刻回复 → respond。"},{"q":"3","answer":"A","options":["constantly","apart","currently","miserably"],"explanation":"不断查看手机 → constantly。"},{"q":"4","answer":"B","options":["attract","annoy","view","locate"],"explanation":"这会惹恼周围人 → annoy。"},{"q":"5","answer":"C","options":["instruct","operate","assume","relate"],"explanation":"不该想当然以为人人都有空 → assume。"},{"q":"6","answer":"D","options":["signal","delay","network","response"],"explanation":"给朋友清楚的回应 → response。"},{"q":"7","answer":"A","options":["emotional","remote","advanced","interactive"],"explanation":"可能伤害情感联系 → emotional bond。"},{"q":"8","answer":"B","options":["demanding","important","flexible","powerful"],"explanation":"最重要的事 → important。"},{"q":"9","answer":"C","options":["far apart","at first","now and then","by sight"],"explanation":"时不时放下手机 → now and then。"},{"q":"10","answer":"D","options":["image","chest","soldier","attention"],"explanation":"给面前的人全部注意力 → full attention。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Choosing a Robot Pet', '上外版必修第三册 U4 · dialogue', 3, 'Mia: I''m thinking of buying that robot dog. It looks so cute.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 Worries About New Technology', '上外版必修第三册 U4 · passage', 2, 'A recent report shows that many people are worried about new technology.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Surgery from Far Away', '上外版必修第三册 U4 · dialogue', 3, 'Nina: Did you hear that a doctor did a heart operation from another city?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 How 5G Is Different', '上外版必修第三册 U4 · passage', 2, 'The 5G network is many times faster than the 4G Internet we currently use.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Setting Up a Smart Home', '上外版必修第三册 U4 · dialogue', 3, 'Dad: This new speaker is supposed to control all the lights. Can you set it up?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 AI in Everyday Life', '上外版必修第三册 U4 · passage', 2, 'Artificial intelligence is already a quiet part of our daily life.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Sharing Views on Online and Traditional Classroom Learning(在线学习与传统课堂学习的异同)', 'Online vs Traditional Classroom Learning', '你的班级正在讨论在线学习与传统课堂学习。请用英语写两段、约80-100词,①第一段写两者的相同点;②第二段写两者的不同点。要求:用比较与对照的连接词(both / likewise / however / unlike / while 等),观点清楚、句句相关。', 'Your class is holding a discussion about online and traditional classroom learning. In about 80-100 words, write two paragraphs: 1) the similarities between the two; 2) the differences between them. Use comparison-and-contrast linking words (both, likewise, however, unlike, while), keep your ideas clear and every sentence on the point.', '["相同点段:both 引出共同特征(都需努力、都有老师指导)","不同点段:unlike / while / however 引出差异(地点、互动、灵活度)","用比较对照连接词组织全文(both / likewise / in contrast / while)","结尾给出自己的看法或小结"]'::jsonb, 70, 100, 'Online and traditional classroom learning share several common features. Both ask students to study hard and to finish their tasks on time, and in both ways a teacher guides the lessons. Likewise, both help us gain real knowledge and skills.
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U4', '{"title":"情态动词完成式(modal + have done)速查","intro":"情态动词完成式用来对「过去」的事作出推测、判断或评价。核心:看语气强弱与语境证据——证据确凿用 must / can''t,只是可能用 may / might / could,带责备或后悔用 should(n''t),白做了用 needn''t。","table":{"headers":["形式","含义 / 例句"],"rows":[["must have done","对过去的肯定推测(几乎确定):She must have left it on the subway."],["can''t / couldn''t have done","对过去的否定推测(断定不可能):He can''t have finished it so fast."],["may / might have done","对过去的可能性推测(不确定):I might have left it in class."],["could have done","过去可能而未发生 / 一种可能:The accident could have been prevented."],["should have done","本应做却没做(责备/后悔):You should have called me."],["shouldn''t have done","不该做却做了(责备/后悔):I shouldn''t have signed up."],["needn''t have done","本不必做却做了(白做了):You needn''t have worried."]]},"specialRules":[{"rule":"推测强弱看证据:有确凿依据→must/can''t;只是猜测→may/might/could","mark":"证据定语气"},{"rule":"must have done 的否定推测不是 mustn''t have,而是 can''t / couldn''t have done","mark":"must↔can''t"},{"rule":"needn''t have done(其实不必却做了)≠ didn''t need to do(根本不必、也没做)","mark":"白做 vs 没做"},{"rule":"could have done 还可表「本可以做到却没做」(惋惜)","mark":"could have = 本可以"}],"why":["情态动词本身管「现在/将来」的态度;要把这种推测或评价移到「过去」,就用 have done 把动作钉在过去——所以是 modal + have + 过去分词。"],"gaokaoPoints":["must have done / can''t have done 的肯定与否定推测对应(高频:否定不用 mustn''t have)。","should have done(本应而未)与 needn''t have done(本不必却做)在语境完形/写作中常考。","may / might / could have done 表不确定可能;could have done 还表「本可以却没」。"],"examVsReal":[{"exam":"He must have left earlier.（考试:确定推测)","real":"He''s gotta have left earlier.","note":"口语里 must have 常说成 must''ve / gotta have,但考试写完整形式"},{"exam":"You should have told me.（考试:责备本应)","real":"You shoulda told me.","note":"口语 should have 常缩成 shoulda,书面仍写 should have done"}]}'::jsonb, 'sufe');
